    b = config.get('body')
    if isinstance(b, dict):
        fld = str(b.get('field') or '').lower()
        raw = str(b.get('answer') or '').strip()
        if raw and ('date' in fld or 'birth' in fld or 'dob' in fld):
            if not _re.match(r'^\d{4}-\d{2}-\d{2}$', raw):
                mn = {'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
                      'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12}
                got = None
                m = _re.search(r'(\d{1,2})\s*(?:st|nd|rd|th)?\s*(?:of\s+)?([A-Za-z]{3,9})\.?,?\s*(\d{2,4})', raw)
                if m and m.group(2)[:3].lower() in mn:
                    got = (int(m.group(3)), mn[m.group(2)[:3].lower()], int(m.group(1)))
                if got is None:
                    m = _re.search(r'([A-Za-z]{3,9})\.?\s+(\d{1,2})(?:st|nd|rd|th)?,?\s*(\d{2,4})', raw)
                    if m and m.group(1)[:3].lower() in mn:
                        got = (int(m.group(3)), mn[m.group(1)[:3].lower()], int(m.group(2)))
                if got is None:
                    m = _re.search(r'\b(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})\b', raw)
                    if m:
                        got = (int(m.group(1)), int(m.group(2)), int(m.group(3)))
                if got is None:
                    m = _re.search(r'\b(\d{1,2})[-/.](\d{1,2})[-/.](\d{2,4})\b', raw)
                    if m:
                        got = (int(m.group(3)), int(m.group(2)), int(m.group(1)))
                if got is not None:
                    y, mo, dd = got
                    if y < 100:
                        y = 2000 + y if y < 30 else 1900 + y
                    try:
                        import datetime as _dt
                        b['answer'] = _dt.date(y, mo, dd).isoformat()
                    except Exception:
                        pass
        elif raw and not _re.match(r'^[\w\s-]+$', raw):
            b['answer'] = _re.sub(r'[^0-9a-zA-Z\- ]', '', raw).strip()
except Exception:
    pass

