try:
    import datetime as _dt
    import re as _re
    b = config.get('body')
    if isinstance(b, dict):
        def _day(name, fallback):
            try:
                return _dt.date.fromisoformat(str(vars.get(name) or fallback)[:10])
            except Exception:
                return None
        today = _day('today_date', None)
        first = _day('callback_date_first', None) or today
        last = _day('callback_date_last', None) or first
        raw = str(b.get('date') or '')
        m = _re.search(r'(\d{4})-(\d{2})-(\d{2})', raw)
        try:
            day = _dt.date(int(m.group(1)), int(m.group(2)), int(m.group(3))) if m else _dt.date.fromisoformat(raw[:10])
        except Exception:
            day = first
        if today is not None and first is not None:
            if day < first:
                day = first
            if day > last:
                day = last
        b['date'] = day.isoformat()
        t = str(b.get('time') or '').strip()
        mt = _re.search(r'(\d{1,2}):?(\d{2})', t)
        try:
            hh, mm = int(mt.group(1)), int(mt.group(2)) if mt else (0, 0)
        except Exception:
            hh, mm = 0, 0
        hi_h = int(str(vars.get('callback_time_to') or '19:00')[:2])
        lo_h = int(str(vars.get('callback_window') or '10:00 to 19:00')[:2])
        if today is not None and day == today:
            nm = _re.search(r'(\d{1,2}):(\d{2})', str(vars.get('now_clock') or ''))
            if nm:
                nh = int(nm.group(1))
                if hh < nh or (hh == nh and mm < int(nm.group(2))):
                    hh, mm = nh + 1, 0
        if hh < lo_h:
            hh, mm = lo_h, 0
        if hh > hi_h:
            hh, mm = hi_h, 0
        b['time'] = '%02d:%02d' % (hh, mm)
except Exception:
    pass

