        if _row is None and _exact is not None:
            _row = next((x for x in _confirmed if isinstance(x, dict) and
                         str(x.get('product_type', '')).lower() == str(_exact.get('type', '')).lower()), None)
        if _row is None and len(_confirmed) == 1:
