            if _row.get('date'): b['date'] = _row.get('date')
        try:
            vars['collection_pending_record'] = _json.dumps({'kind':'promise','product_id':pid})
        except Exception:
            pass
        rules = _pp.get(pid) or list(_pp.values())[0] or dict()
        allowed = list(rules.get('allowed') or [])
        if allowed:
            raw = str(b.get('date') or '').strip()
            day = None
            m = __import__('re').search(r'(\d{4})-(\d{2})-(\d{2})', raw)
            if m:
                try:
                    day = _dt.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
                except Exception:
                    day = None
            if day is None:
                try:
                    day = _dt.date.fromisoformat(raw[:10])
                except Exception:
                    day = None
            if day is None:
                day = _dt.date.fromisoformat(str(rules.get('max'))[:10])
            else:
                iso = day.isoformat()
                if iso not in allowed:
                    later = [a for a in allowed if a >= iso]
                    day = _dt.date.fromisoformat(later[0] if later else allowed[-1])
            b['date'] = day.isoformat()
            try:
                amt = float(b.get('amount'))
            except Exception:
                amt = None
            if amt is None:
                amt = rules.get('floor')
            if amt is not None:
                lo = float(rules.get('floor') or 0.0)
                hi = float(rules.get('full') or 0.0)
                if lo and amt < lo:
                    amt = lo
                if hi and amt > hi:
                    amt = hi
                b['amount'] = round(amt, 2)
